import { Router } from 'express';
import { prisma } from '../../infrastructure/database/prisma';
const router = Router();
router.get('/', async (req,res)=>{
  const {q, categoryId, page=1, limit=20}=req.query as any;
  const skip=(Number(page)-1)*Number(limit);
  const where:any={active:true};
  if(q) where.name={contains:String(q), mode:'insensitive'};
  if(categoryId) where.categoryId=String(categoryId);
  const [items,total]=await Promise.all([prisma.product.findMany({where,skip,take:Number(limit),include:{images:true,inventory:true}}), prisma.product.count({where})]);
  res.json({items,total,page:Number(page),limit:Number(limit)});
});
router.get('/:slug', async (req,res)=>{ const item = await prisma.product.findUnique({where:{slug:req.params.slug},include:{images:true,inventory:true,category:true}}); if(!item)return res.status(404).json({error:'Not found'}); res.json(item); });
export default router;
